function uid(prefix) {
  return prefix + '_' + Math.random().toString(36).slice(2, 9);
}

function combinations(arr, k) {
  const result = [];
  function backtrack(start, combo) {
    if (combo.length === k) { result.push([...combo]); return; }
    for (let i = start; i < arr.length; i++) {
      combo.push(arr[i]);
      backtrack(i + 1, combo);
      combo.pop();
    }
  }
  backtrack(0, []);
  return result;
}

function armarEquipos(convocados, players) {
  const n = convocados.length;
  const sizeA = Math.ceil(n / 2);
  const levelOf = (id) => players.find((p) => p.id === id)?.nivel || 3;
  const total = convocados.reduce((s, id) => s + levelOf(id), 0);
  let best = null;
  let bestDiff = Infinity;
  for (const teamA of combinations(convocados, sizeA)) {
    const teamB = convocados.filter((id) => !teamA.includes(id));
    const sumA = teamA.reduce((s, id) => s + levelOf(id), 0);
    const diff = Math.abs(sumA - (total - sumA));
    if (diff < bestDiff) { bestDiff = diff; best = { teamA, teamB }; }
  }
  return best;
}

const FONDO_CARTEL = "data:image/jpeg;base64,";

function cargarImagen(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });
}

function dibujarRectRedondeado(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

async function dibujarCartel({ titulo, subtitulo, lineas }) {
  const canvas = document.createElement('canvas');
  canvas.width = 800;
  canvas.height = 1000;
  const ctx = canvas.getContext('2d');

  // Fondo: foto de pelota y arco, cubriendo todo el cartel
  const fondo = await cargarImagen(FONDO_CARTEL);
  const escala = Math.max(canvas.width / fondo.width, canvas.height / fondo.height);
  const anchoRecorte = canvas.width / escala;
  const altoRecorte = canvas.height / escala;
  const recorteX = (fondo.width - anchoRecorte) / 2;
  const recorteY = (fondo.height - altoRecorte) / 2;
  ctx.drawImage(fondo, recorteX, recorteY, anchoRecorte, altoRecorte, 0, 0, canvas.width, canvas.height);

  // Sombra suave arriba para que el título en blanco se lea bien
  const gradiente = ctx.createLinearGradient(0, 0, 0, 260);
  gradiente.addColorStop(0, 'rgba(10,15,15,0.8)');
  gradiente.addColorStop(1, 'rgba(10,15,15,0.05)');
  ctx.fillStyle = gradiente;
  ctx.fillRect(0, 0, canvas.width, 260);

  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'center';
  ctx.font = 'bold 44px sans-serif';
  ctx.fillText(titulo, 400, 110);
  if (subtitulo) {
    ctx.font = '24px sans-serif';
    ctx.fillStyle = 'rgba(255,255,255,0.85)';
    ctx.fillText(subtitulo, 400, 150);
  }

  // Recuadro translúcido y legible para los datos, sobre el resto de la foto
  const cajaY = 220;
  const cajaAlto = canvas.height - cajaY - 40;
  ctx.fillStyle = 'rgba(255,255,255,0.9)';
  dibujarRectRedondeado(ctx, 40, cajaY, canvas.width - 80, cajaAlto, 20);
  ctx.fill();

  ctx.textAlign = 'left';
  ctx.font = '28px sans-serif';
  let y = cajaY + 50;
  const limiteY = cajaY + cajaAlto - 20;
  for (const linea of lineas) {
    if (y > limiteY) break;
    if (linea.header) {
      ctx.font = 'bold 28px sans-serif';
      ctx.fillStyle = '#0f6e56';
      ctx.fillText(linea.header, 70, y);
      ctx.font = '28px sans-serif';
      y += 40;
      continue;
    }
    ctx.fillStyle = '#292524';
    ctx.fillText(linea.text || linea, 70, y);
    y += 36;
  }
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function compartir(datos) {
  const blob = await dibujarCartel(datos);
  const file = new File([blob], 'futbol5.png', { type: 'image/png' });
  try {
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({ files: [file], title: datos.titulo });
      return;
    }
  } catch (e) {}
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'futbol5.png';
  a.click();
}

