// ---------- Jugadores ----------

function JugadoresScreen({ players, savePlayers }) {
  const [showForm, setShowForm] = useState(false);
  const [nombre, setNombre] = useState('');
  const [posicion, setPosicion] = useState(POSICIONES[2]);
  const [nivel, setNivel] = useState(3);
  const [editId, setEditId] = useState(null);

  function abrirNuevo() {
    setEditId(null);
    setNombre('');
    setPosicion(POSICIONES[2]);
    setNivel(3);
    setShowForm(true);
  }

  function abrirEditar(p) {
    setEditId(p.id);
    setNombre(p.nombre);
    setPosicion(p.posicion);
    setNivel(p.nivel);
    setShowForm(true);
  }

  function guardar() {
    if (!nombre.trim()) return;
    if (editId) {
      savePlayers(players.map((p) => (p.id === editId ? { ...p, nombre, posicion, nivel } : p)));
    } else {
      savePlayers([...players, { id: uid('j'), nombre, posicion, nivel, activo: true }]);
    }
    setShowForm(false);
  }

  function eliminar(id) {
    savePlayers(players.filter((p) => p.id !== id));
  }

  if (showForm) {
    return (
      <div className="max-w-md mx-auto">
        <Board title={editId ? 'Editar jugador' : 'Nuevo jugador'} subtitle="Datos básicos">
          <button onClick={() => setShowForm(false)} className="absolute top-6 right-5 text-emerald-200">
            <X size={20} />
          </button>
        </Board>
        <div className="bg-white rounded-b-2xl p-5 border border-t-0 border-stone-200">
          <label className="text-sm text-stone-500 block mb-1">Nombre</label>
          <input
            className="w-full border border-stone-300 rounded-lg px-3 py-2 mb-4 text-stone-800"
            placeholder="Facundo Rodríguez"
            value={nombre}
            onChange={(e) => setNombre(e.target.value)}
          />
          <label className="text-sm text-stone-500 block mb-1">Posición</label>
          <select
            className="w-full border border-stone-300 rounded-lg px-3 py-2 mb-4 text-stone-800"
            value={posicion}
            onChange={(e) => setPosicion(e.target.value)}
          >
            {POSICIONES.map((p) => <option key={p}>{p}</option>)}
          </select>
          <label className="text-sm text-stone-500 block mb-2">Nivel</label>
          <div className="flex gap-2 mb-1">
            {[1, 2, 3, 4, 5].map((n) => (
              <button
                key={n}
                onClick={() => setNivel(n)}
                className={'w-11 h-11 rounded-lg font-medium ' + (n === nivel ? 'bg-emerald-600 text-white' : 'bg-stone-100 text-stone-500')}
              >
                {n}
              </button>
            ))}
          </div>
          <p className="text-xs text-stone-400 mb-5">Tu criterio, se puede editar después</p>
          <button onClick={guardar} className="w-full bg-emerald-800 text-white rounded-lg py-3 font-medium">
            Guardar jugador
          </button>
          {editId && (
            <button
              onClick={() => { eliminar(editId); setShowForm(false); }}
              className="w-full text-red-600 text-sm mt-3 flex items-center justify-center gap-1"
            >
              <Trash2 size={14} /> Eliminar jugador
            </button>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto">
      <div className="flex items-center justify-between mb-4">
        <h1 className="text-lg font-medium text-stone-800">Jugadores</h1>
        <button onClick={abrirNuevo} className="bg-emerald-800 text-white rounded-lg px-3 py-2 text-sm flex items-center gap-1">
          <Plus size={16} /> Agregar
        </button>
      </div>
      {players.length === 0 && (
        <p className="text-stone-400 text-sm text-center py-10">Todavía no agregaste jugadores.</p>
      )}
      <div className="flex flex-col gap-2">
        {players.map((p) => (
          <button
            key={p.id}
            onClick={() => abrirEditar(p)}
            className="bg-white border border-stone-200 rounded-xl p-3 flex items-center gap-3 text-left"
          >
            <Avatar nombre={p.nombre} />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-stone-800 truncate">{p.nombre}</p>
              <p className="text-xs text-stone-400">{p.posicion}</p>
            </div>
            <NivelDots nivel={p.nivel} />
          </button>
        ))}
      </div>
    </div>
  );
}

// ---------- Partido ----------

function PartidoScreen({ players, matches, saveMatches }) {
  const activo = matches.find((m) => m.estado !== 'jugado');
  const [fecha, setFecha] = useState(() => new Date().toISOString().slice(0, 10));
  const [resultOpen, setResultOpen] = useState(false);
  const [verId, setVerId] = useState(null);

  function crearPartido() {
    const nuevo = {
      id: uid('p'),
      fecha,
      estado: 'convocando',
      convocados: [],
      equipoA: [],
      equipoB: [],
      resultado: { golesRegistrados: false, golesPorJugador: {}, golesEquipoA: 0, golesEquipoB: 0, mvp: null, ganador: null },
    };
    saveMatches([...matches, nuevo]);
  }

  function actualizar(cambios) {
    saveMatches(matches.map((m) => (m.id === activo.id ? { ...m, ...cambios } : m)));
  }

  function toggleConvocado(id) {
    const set = new Set(activo.convocados);
    set.has(id) ? set.delete(id) : set.add(id);
    actualizar({ convocados: [...set] });
  }

  function ingresarPartido() {
    const { teamA, teamB } = armarEquipos(activo.convocados, players);
    actualizar({ estado: 'armado', equipoA: teamA, equipoB: teamB });
  }

  function cancelarPartido() {
    saveMatches(matches.filter((m) => m.id !== activo.id));
  }

  function volverAConvocatoria() {
    actualizar({ estado: 'convocando', equipoA: [], equipoB: [] });
  }

  function moverJugador(id, hacia) {
    const equipoA = activo.equipoA.filter((x) => x !== id);
    const equipoB = activo.equipoB.filter((x) => x !== id);
    if (hacia === 'A') equipoA.push(id);
    else equipoB.push(id);
    actualizar({ equipoA, equipoB });
  }

  const nombreDe = (id) => players.find((p) => p.id === id)?.nombre || '?';

  const verPartido = verId ? matches.find((m) => m.id === verId) : null;
  if (verPartido) {
    return (
      <div className="max-w-md mx-auto">
        <button onClick={() => setVerId(null)} className="flex items-center gap-1 text-sm text-stone-500 mb-3">
          <ChevronLeft size={16} /> Volver al historial
        </button>
        <ResumenPartido partido={verPartido} players={players} />
      </div>
    );
  }

  if (!activo) {
    return (
      <div className="max-w-md mx-auto">
        <h1 className="text-lg font-medium text-stone-800 mb-4">Partido</h1>
        <div className="bg-white border border-stone-200 rounded-2xl p-6 text-center">
          <p className="text-stone-500 text-sm mb-4">No hay ningún partido en curso.</p>
          <label className="text-sm text-stone-500 block mb-1">Fecha</label>
          <input
            type="date"
            className="w-full border border-stone-300 rounded-lg px-3 py-2 mb-4 text-stone-800"
            value={fecha}
            onChange={(e) => setFecha(e.target.value)}
          />
          <button onClick={crearPartido} className="w-full bg-emerald-800 text-white rounded-lg py-3 font-medium">
            Crear partido
          </button>
        </div>
        <HistorialPartidos matches={matches} players={players} onSelect={setVerId} />
      </div>
    );
  }

  if (activo.estado === 'convocando') {
    return (
      <div className="max-w-md mx-auto">
        <button onClick={cancelarPartido} className="flex items-center gap-1 text-sm text-stone-500 mb-3">
          <ChevronLeft size={16} /> Volver (cancela este partido)
        </button>
        <Board title={new Date(activo.fecha + 'T12:00').toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' })} subtitle="Convocatoria" />
        <div className="bg-white rounded-b-2xl p-4 border border-t-0 border-stone-200">
          <p className="text-sm text-stone-500 mb-3">{activo.convocados.length} anotados</p>
          <div className="flex flex-col gap-2 mb-4">
            {players.map((p) => {
              const on = activo.convocados.includes(p.id);
              return (
                <button
                  key={p.id}
                  onClick={() => toggleConvocado(p.id)}
                  className={'flex items-center gap-3 rounded-xl p-2 border ' + (on ? 'bg-emerald-50 border-emerald-300' : 'border-stone-200')}
                >
                  <Avatar nombre={p.nombre} size={34} />
                  <span className="text-sm text-stone-800 flex-1 text-left">{p.nombre}</span>
                  {on && <Check size={18} className="text-emerald-600" />}
                </button>
              );
            })}
          </div>
          <button
            disabled={activo.convocados.length < 2}
            onClick={ingresarPartido}
            className="w-full bg-emerald-800 text-white rounded-lg py-3 font-medium disabled:opacity-40"
          >
            Ingresar partido
          </button>
        </div>
      </div>
    );
  }

  if (activo.estado === 'armado') {
    return (
      <div className="max-w-md mx-auto">
        <button onClick={volverAConvocatoria} className="flex items-center gap-1 text-sm text-stone-500 mb-3">
          <ChevronLeft size={16} /> Volver a la convocatoria
        </button>
        <Board title="Equipos sugeridos" subtitle="Tocá un jugador para cambiarlo de equipo" />
        <div className="bg-white rounded-b-2xl p-4 border border-t-0 border-stone-200">
          <div className="grid grid-cols-2 gap-3 mb-4">
            <div>
              <p className="text-xs font-medium text-emerald-700 mb-2">Equipo A</p>
              <div className="flex flex-col gap-1.5">
                {activo.equipoA.map((id) => (
                  <button key={id} onClick={() => moverJugador(id, 'B')} className="flex items-center justify-between bg-emerald-50 rounded-lg px-2 py-2 text-left">
                    <span className="text-xs text-stone-800 truncate">{nombreDe(id)}</span>
                    <ArrowLeftRight size={12} className="text-stone-400 flex-shrink-0" />
                  </button>
                ))}
              </div>
            </div>
            <div>
              <p className="text-xs font-medium text-orange-700 mb-2">Equipo B</p>
              <div className="flex flex-col gap-1.5">
                {activo.equipoB.map((id) => (
                  <button key={id} onClick={() => moverJugador(id, 'A')} className="flex items-center justify-between bg-orange-50 rounded-lg px-2 py-2 text-left">
                    <span className="text-xs text-stone-800 truncate">{nombreDe(id)}</span>
                    <ArrowLeftRight size={12} className="text-stone-400 flex-shrink-0" />
                  </button>
                ))}
              </div>
            </div>
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => compartir({
                titulo: 'Equipos',
                subtitulo: new Date(activo.fecha + 'T12:00').toLocaleDateString('es-AR'),
                lineas: [
                  { header: 'Equipo A' }, ...activo.equipoA.map((id) => ({ text: nombreDe(id) })),
                  { header: 'Equipo B' }, ...activo.equipoB.map((id) => ({ text: nombreDe(id) })),
                ],
              })}
              className="flex-1 border border-stone-300 text-stone-700 rounded-lg py-3 font-medium flex items-center justify-center gap-2"
            >
              <Share2 size={16} /> Compartir
            </button>
            <button onClick={() => setResultOpen(true)} className="flex-1 bg-emerald-800 text-white rounded-lg py-3 font-medium">
              Cargar resultado
            </button>
          </div>
        </div>
        {resultOpen && <ResultadoModal partido={activo} players={players} onClose={() => setResultOpen(false)} onGuardar={(resultado) => { actualizar({ estado: 'jugado', resultado }); setResultOpen(false); }} />}
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto">
      <ResumenPartido partido={activo} players={players} />
      <button onClick={crearPartido} className="w-full bg-emerald-800 text-white rounded-lg py-3 font-medium mt-3">
        Crear próximo partido
      </button>
      <HistorialPartidos matches={matches} players={players} onSelect={setVerId} />
    </div>
  );
}

function ResultadoModal({ partido, players, onClose, onGuardar }) {
  const [golesA, setGolesA] = useState(0);
  const [golesB, setGolesB] = useState(0);
  const [golesReg, setGolesReg] = useState(false);
  const [goles, setGoles] = useState({});
  const [mvp, setMvp] = useState(null);
  const nombreDe = (id) => players.find((p) => p.id === id)?.nombre || '?';

  function guardar() {
    const ganador = golesA > golesB ? 'A' : golesA < golesB ? 'B' : 'empate';
    onGuardar({
      golesEquipoA: golesA,
      golesEquipoB: golesB,
      golesRegistrados: golesReg,
      golesPorJugador: golesReg ? goles : {},
      mvp,
      ganador,
    });
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-40 flex items-end justify-center z-10" style={{ position: 'absolute' }}>
      <div className="bg-white rounded-t-2xl p-5 w-full max-w-md max-h-[80vh] overflow-y-auto">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-medium text-stone-800">Cargar resultado</h2>
          <button onClick={onClose}><X size={20} className="text-stone-400" /></button>
        </div>

        <p className="text-sm text-stone-500 mb-2">Goles por equipo</p>
        <div className="flex items-center justify-center gap-4 mb-5">
          <div className="text-center">
            <p className="text-xs text-emerald-700 mb-1">Equipo A</p>
            <input type="number" min="0" className="w-16 border border-stone-300 rounded-lg px-2 py-2 text-center text-lg" value={golesA} onChange={(e) => setGolesA(parseInt(e.target.value) || 0)} />
          </div>
          <span className="text-stone-300 text-xl mt-4">-</span>
          <div className="text-center">
            <p className="text-xs text-orange-700 mb-1">Equipo B</p>
            <input type="number" min="0" className="w-16 border border-stone-300 rounded-lg px-2 py-2 text-center text-lg" value={golesB} onChange={(e) => setGolesB(parseInt(e.target.value) || 0)} />
          </div>
        </div>

        <label className="flex items-center gap-2 mb-4">
          <input type="checkbox" checked={golesReg} onChange={(e) => setGolesReg(e.target.checked)} />
          <span className="text-sm text-stone-600">Registrar goles por jugador (opcional)</span>
        </label>
        {golesReg && (
          <div className="flex flex-col gap-2 mb-5">
            {partido.convocados.map((id) => (
              <div key={id} className="flex items-center justify-between">
                <span className="text-sm text-stone-700">{nombreDe(id)}</span>
                <input
                  type="number"
                  min="0"
                  className="w-16 border border-stone-300 rounded-lg px-2 py-1 text-center"
                  value={goles[id] || 0}
                  onChange={(e) => setGoles({ ...goles, [id]: parseInt(e.target.value) || 0 })}
                />
              </div>
            ))}
          </div>
        )}

        <p className="text-sm text-stone-500 mb-2">MVP (opcional)</p>
        <select className="w-full border border-stone-300 rounded-lg px-3 py-2 mb-5" value={mvp || ''} onChange={(e) => setMvp(e.target.value || null)}>
          <option value="">Sin MVP</option>
          {partido.convocados.map((id) => <option key={id} value={id}>{nombreDe(id)}</option>)}
        </select>

        <button onClick={guardar} className="w-full bg-emerald-800 text-white rounded-lg py-3 font-medium">
          Guardar resultado
        </button>
      </div>
    </div>
  );
}

function ResumenPartido({ partido, players }) {
  const nombreDe = (id) => players.find((p) => p.id === id)?.nombre || '?';
  const r = partido.resultado;
  const golesA = r.golesEquipoA ?? 0;
  const golesB = r.golesEquipoB ?? 0;
  const ganadorTexto = r.ganador === 'empate' ? 'Empate' : r.ganador === 'A' ? 'Ganó equipo A' : 'Ganó equipo B';
  return (
    <div>
      <Board title={new Date(partido.fecha + 'T12:00').toLocaleDateString('es-AR', { day: 'numeric', month: 'long' })} subtitle="Resultado" />
      <div className="bg-white rounded-b-2xl p-4 border border-t-0 border-stone-200">
        <div className="flex items-center justify-center gap-4 mb-4">
          <span className="text-2xl font-medium text-emerald-700">{golesA}</span>
          <div className="flex items-center gap-1 text-xs text-stone-400">
            <Trophy size={14} className="text-emerald-700" /> {ganadorTexto}
          </div>
          <span className="text-2xl font-medium text-orange-700">{golesB}</span>
        </div>
        <div className="grid grid-cols-2 gap-3 mb-4">
          <div>
            <p className="text-xs font-medium text-emerald-700 mb-1">Equipo A</p>
            {partido.equipoA.map((id) => (
              <p key={id} className="text-xs text-stone-600 py-0.5">
                {nombreDe(id)}{r.golesRegistrados && r.golesPorJugador[id] ? ' (' + r.golesPorJugador[id] + ')' : ''}
                {r.mvp === id && <Star size={10} className="inline ml-1 text-amber-500" />}
              </p>
            ))}
          </div>
          <div>
            <p className="text-xs font-medium text-orange-700 mb-1">Equipo B</p>
            {partido.equipoB.map((id) => (
              <p key={id} className="text-xs text-stone-600 py-0.5">
                {nombreDe(id)}{r.golesRegistrados && r.golesPorJugador[id] ? ' (' + r.golesPorJugador[id] + ')' : ''}
                {r.mvp === id && <Star size={10} className="inline ml-1 text-amber-500" />}
              </p>
            ))}
          </div>
        </div>
        <button
          onClick={() => compartir({
            titulo: golesA + ' - ' + golesB,
            subtitulo: ganadorTexto + ' · ' + new Date(partido.fecha + 'T12:00').toLocaleDateString('es-AR'),
            lineas: [
              { header: 'Equipo A' }, ...partido.equipoA.map((id) => ({ text: nombreDe(id) + (r.golesRegistrados && r.golesPorJugador[id] ? ' - ' + r.golesPorJugador[id] + ' gol(es)' : '') })),
              { header: 'Equipo B' }, ...partido.equipoB.map((id) => ({ text: nombreDe(id) + (r.golesRegistrados && r.golesPorJugador[id] ? ' - ' + r.golesPorJugador[id] + ' gol(es)' : '') })),
            ],
          })}
          className="w-full border border-stone-300 text-stone-700 rounded-lg py-3 font-medium flex items-center justify-center gap-2"
        >
          <Share2 size={16} /> Compartir resultado
        </button>
      </div>
    </div>
  );
}

function HistorialPartidos({ matches, players, onSelect }) {
  const jugados = matches.filter((m) => m.estado === 'jugado').slice().reverse();
  if (jugados.length === 0) return null;
  return (
    <div className="mt-6">
      <p className="text-sm font-medium text-stone-500 mb-2">Historial</p>
      <div className="flex flex-col gap-2">
        {jugados.map((m) => (
          <button key={m.id} onClick={() => onSelect(m.id)} className="bg-white border border-stone-200 rounded-xl p-3 flex items-center justify-between text-left">
            <span className="text-sm text-stone-700">{new Date(m.fecha + 'T12:00').toLocaleDateString('es-AR', { day: 'numeric', month: 'short' })}</span>
            <span className="text-xs font-medium text-stone-600 flex items-center gap-2">
              {m.resultado.golesEquipoA ?? 0} - {m.resultado.golesEquipoB ?? 0}
              {m.resultado.ganador === 'empate' && <span className="text-stone-400 font-normal">(empate)</span>}
              <ChevronRight size={14} className="text-stone-300" />
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

// ---------- Estadísticas ----------

function calcularStats(players, matches) {
  const jugados = matches.filter((m) => m.estado === 'jugado');
  const UMBRAL_INACTIVIDAD_DIAS = 45;

  function diasSinJugarDe(id) {
    const propios = jugados.filter((m) => m.equipoA.includes(id) || m.equipoB.includes(id));
    if (propios.length === 0) return null;
    const ultima = propios.reduce((max, m) => (m.fecha > max ? m.fecha : max), propios[0].fecha);
    return Math.floor((Date.now() - new Date(ultima + 'T12:00').getTime()) / (1000 * 60 * 60 * 24));
  }

  function base(id) {
    let pj = 0, g = 0, e = 0, p = 0, goles = 0;
    for (const m of jugados) {
      const inA = m.equipoA.includes(id), inB = m.equipoB.includes(id);
      if (!inA && !inB) continue;
      pj++;
      const team = inA ? 'A' : 'B';
      if (m.resultado.ganador === 'empate') e++;
      else if (m.resultado.ganador === team) g++;
      else p++;
      if (m.resultado.golesRegistrados) goles += m.resultado.golesPorJugador?.[id] || 0;
    }
    return { pj, g, e, p, goles, efectividad: pj > 0 ? Math.round((g / pj) * 100) : 0 };
  }

  const ranking = players.map((pl) => ({ ...pl, ...base(pl.id), diasSinJugar: diasSinJugarDe(pl.id) }));

  function duplas() {
    const map = {};
    for (const m of jugados) {
      for (const team of [m.equipoA, m.equipoB]) {
        const gano = (team === m.equipoA && m.resultado.ganador === 'A') || (team === m.equipoB && m.resultado.ganador === 'B');
        for (let i = 0; i < team.length; i++) {
          for (let j = i + 1; j < team.length; j++) {
            const key = [team[i], team[j]].sort().join('|');
            if (!map[key]) map[key] = { a: team[i], b: team[j], jugados: 0, ganados: 0 };
            map[key].jugados++;
            if (gano) map[key].ganados++;
          }
        }
      }
    }
    return Object.values(map).filter((d) => d.jugados >= 3).map((d) => ({ ...d, pct: Math.round((d.ganados / d.jugados) * 100) })).sort((a, b) => b.pct - a.pct);
  }

  function cabezaACabeza() {
    const map = {};
    for (const m of jugados) {
      if (m.resultado.ganador === 'empate') continue;
      const winners = m.resultado.ganador === 'A' ? m.equipoA : m.equipoB;
      const losers = m.resultado.ganador === 'A' ? m.equipoB : m.equipoA;
      for (const w of winners) for (const l of losers) {
        const key = w + '>' + l;
        map[key] = (map[key] || 0) + 1;
      }
    }
    return Object.entries(map).filter(([, n]) => n >= 3).map(([key, n]) => {
      const [ganador, perdedor] = key.split('>');
      return { ganador, perdedor, n };
    }).sort((a, b) => b.n - a.n);
  }

  function rachaDe(id) {
    const propios = jugados.filter((m) => m.equipoA.includes(id) || m.equipoB.includes(id)).slice().sort((a, b) => a.fecha.localeCompare(b.fecha));
    let tipo = null, streak = 0, mejorG = 0, actualG = 0, mejorP = 0, actualP = 0;
    for (const m of propios) {
      const team = m.equipoA.includes(id) ? 'A' : 'B';
      const res = m.resultado.ganador === 'empate' ? 'E' : m.resultado.ganador === team ? 'G' : 'P';
      actualG = res === 'G' ? actualG + 1 : 0;
      mejorG = Math.max(mejorG, actualG);
      actualP = res === 'P' ? actualP + 1 : 0;
      mejorP = Math.max(mejorP, actualP);
    }
    for (let i = propios.length - 1; i >= 0; i--) {
      const m = propios[i];
      const team = m.equipoA.includes(id) ? 'A' : 'B';
      const res = m.resultado.ganador === 'empate' ? 'E' : m.resultado.ganador === team ? 'G' : 'P';
      if (tipo === null) { tipo = res; streak = 1; }
      else if (res === tipo) streak++;
      else break;
    }
    return { tipo, streak, mejorRachaGanadora: mejorG, mejorRachaPerdedora: mejorP };
  }

  function mejorDuplaDe(id) {
    return duplas().filter((d) => d.a === id || d.b === id).sort((a, b) => b.pct - a.pct)[0] || null;
  }

  function grupo() {
    const asistencia = players.map((pl) => ({ ...pl, pct: jugados.length > 0 ? Math.round((base(pl.id).pj / jugados.length) * 100) : 0 })).sort((a, b) => b.pct - a.pct);
    const empates = jugados.length > 0 ? Math.round((jugados.filter((m) => m.resultado.ganador === 'empate').length / jugados.length) * 100) : 0;
    return { asistencia, empates };
  }

  function mejorVictoriaDe(id) {
    let best = null;
    for (const m of jugados) {
      const inA = m.equipoA.includes(id), inB = m.equipoB.includes(id);
      if (!inA && !inB) continue;
      const team = inA ? 'A' : 'B';
      if (m.resultado.ganador !== team) continue;
      const propios = team === 'A' ? (m.resultado.golesEquipoA ?? 0) : (m.resultado.golesEquipoB ?? 0);
      const rivales = team === 'A' ? (m.resultado.golesEquipoB ?? 0) : (m.resultado.golesEquipoA ?? 0);
      const diff = propios - rivales;
      if (!best || diff > best.diff) best = { partido: m, diff, propios, rivales };
    }
    return best;
  }

  function peorDerrotaDe(id) {
    let worst = null;
    for (const m of jugados) {
      const inA = m.equipoA.includes(id), inB = m.equipoB.includes(id);
      if (!inA && !inB) continue;
      const team = inA ? 'A' : 'B';
      const rival = team === 'A' ? 'B' : 'A';
      if (m.resultado.ganador !== rival) continue;
      const propios = team === 'A' ? (m.resultado.golesEquipoA ?? 0) : (m.resultado.golesEquipoB ?? 0);
      const rivales = team === 'A' ? (m.resultado.golesEquipoB ?? 0) : (m.resultado.golesEquipoA ?? 0);
      const diff = rivales - propios;
      if (!worst || diff > worst.diff) worst = { partido: m, diff, propios, rivales };
    }
    return worst;
  }

  // Tabla de cambio de nivel según victorias/empates/derrotas de los últimos 5 partidos
  const TABLA_CAMBIO = {
    '5-0-0': 2, '4-1-0': 2, '4-0-1': 1, '3-2-0': 1, '3-1-1': 1, '3-0-2': 0,
    '2-3-0': 1, '2-2-1': 0, '2-1-2': 0, '2-0-3': -1, '1-4-0': 0, '1-3-1': 0,
    '1-2-2': 0, '1-1-3': -1, '1-0-4': -2, '0-5-0': 0, '0-4-1': -1, '0-3-2': -1,
    '0-2-3': -1, '0-1-4': -2, '0-0-5': -2,
  };

  const UMBRAL_RESET_ESTRELLAS_DIAS = 60;

  function nivelEstrellasDe(id) {
    const propios = jugados.filter((m) => m.equipoA.includes(id) || m.equipoB.includes(id)).slice().sort((a, b) => a.fecha.localeCompare(b.fecha));
    const ultimos5 = propios.slice(-5);
    const resultados = ultimos5.map((m) => {
      const team = m.equipoA.includes(id) ? 'A' : 'B';
      return m.resultado.ganador === 'empate' ? 'E' : m.resultado.ganador === team ? 'V' : 'D';
    });
    if (resultados.length < 5) return { nivel: null, resultados };
    const dias = diasSinJugarDe(id);
    if (dias !== null && dias > UMBRAL_RESET_ESTRELLAS_DIAS) return { nivel: 0, resultados };
    const v = resultados.filter((r) => r === 'V').length;
    const e = resultados.filter((r) => r === 'E').length;
    const d = resultados.filter((r) => r === 'D').length;
    const cambio = TABLA_CAMBIO[v + '-' + e + '-' + d] ?? 0;
    const nivel = Math.max(1, Math.min(10, 5 + cambio));
    return { nivel, resultados };
  }

  const estrellasRanking = players.map((pl) => ({ ...pl, ...nivelEstrellasDe(pl.id), diasSinJugar: diasSinJugarDe(pl.id) })).sort((a, b) => (b.nivel ?? -1) - (a.nivel ?? -1));

  return { ranking, jugados, duplas: duplas(), cabezaACabeza: cabezaACabeza(), rachaDe, mejorDuplaDe, mejorVictoriaDe, peorDerrotaDe, grupo: grupo(), nivelEstrellasDe, estrellasRanking, UMBRAL_INACTIVIDAD_DIAS, UMBRAL_RESET_ESTRELLAS_DIAS };
}

function StatsScreen({ players, matches }) {
  const [tab, setTab] = useState('ranking');
  const [jugadorId, setJugadorId] = useState(null);
  const [infoAbierto, setInfoAbierto] = useState(null);
  const stats = useMemo(() => calcularStats(players, matches), [players, matches]);
  const nombreDe = (id) => players.find((p) => p.id === id)?.nombre || '?';

  if (jugadorId) {
    const pl = players.find((p) => p.id === jugadorId);
    const b = stats.ranking.find((r) => r.id === jugadorId);
    const racha = stats.rachaDe(jugadorId);
    const dupla = stats.mejorDuplaDe(jugadorId);
    const mejorVictoria = stats.mejorVictoriaDe(jugadorId);
    const peorDerrota = stats.peorDerrotaDe(jugadorId);
    const estrellas = stats.nivelEstrellasDe(jugadorId);
    const fechaCorta = (f) => new Date(f + 'T12:00').toLocaleDateString('es-AR', { day: 'numeric', month: 'long' });
    return (
      <div className="-m-4 p-4" style={{ backgroundImage: `linear-gradient(rgba(245,245,244,0.55), rgba(245,245,244,0.65)), url(${FONDO_ESTADIO})`, backgroundSize: 'cover', backgroundPosition: 'center' }}>
      <div className="max-w-md mx-auto">
        <button onClick={() => setJugadorId(null)} className="flex items-center gap-1 text-sm text-stone-500 mb-3">
          <ChevronLeft size={16} /> Volver
        </button>
        <Board title={pl.nombre} subtitle={pl.posicion} />
        <div className="rounded-b-2xl p-4 border border-t-0 border-stone-200" style={TARJETA_STATS}>
          <div className="mb-4">
            <div className="flex items-center justify-between mb-1">
              <p className="text-xs text-stone-500">Estrellas de calidad</p>
              <p className="text-sm font-medium text-stone-800">{estrellas.nivel ?? '-'}/10</p>
            </div>
            <EstrellasRow nivel={estrellas.nivel} />
            <UltimosCirculos resultados={estrellas.resultados} />
          </div>
          <div className="grid grid-cols-3 gap-2 mb-2">
            <StatCard label="Partidos" value={b.pj} />
            <StatCard label="Ganados" value={b.g} />
            <StatCard label="Perdidos" value={b.p} />
          </div>
          <div className="grid grid-cols-3 gap-2 mb-4">
            <StatCard label="Empatados" value={b.e} />
            <StatCard label="Efectividad" value={b.efectividad + '%'} />
            <StatCard label="Goles" value={b.goles} />
          </div>
          <div className="border-t border-stone-100 pt-3 flex flex-col gap-2">
            <p className="text-sm text-stone-700">
              Racha actual: {racha.tipo ? racha.streak + ' ' + (racha.tipo === 'G' ? 'ganados seguidos' : racha.tipo === 'P' ? 'perdidos seguidos' : 'empates seguidos') : 'sin partidos'}
            </p>
            <p className="text-sm text-stone-700">
              Mejor dupla: {dupla ? nombreDe(dupla.a === jugadorId ? dupla.b : dupla.a) + ' (' + dupla.pct + '% ganados juntos)' : 'todavía sin datos suficientes'}
            </p>
            <p className="text-sm text-stone-700">
              Mejor victoria: {mejorVictoria ? mejorVictoria.propios + ' - ' + mejorVictoria.rivales + ' el ' + fechaCorta(mejorVictoria.partido.fecha) + ' (+' + mejorVictoria.diff + ')' : 'todavía sin victorias'}
            </p>
            <p className="text-sm text-stone-700">
              Peor derrota: {peorDerrota ? peorDerrota.propios + ' - ' + peorDerrota.rivales + ' el ' + fechaCorta(peorDerrota.partido.fecha) + ' (-' + peorDerrota.diff + ')' : 'todavía sin derrotas'}
            </p>
          </div>
          <button
            onClick={() => compartir({
              titulo: pl.nombre,
              subtitulo: b.pj + ' partidos jugados',
              lineas: [
                { text: 'Efectividad: ' + b.efectividad + '%' },
                { text: 'Goles: ' + b.goles },
                { text: 'G/E/P: ' + b.g + '/' + b.e + '/' + b.p },
                { text: 'Estrellas de calidad: ' + (estrellas.nivel ?? '-') + '/10' },
              ],
            })}
            className="w-full border border-stone-300 text-stone-700 rounded-lg py-3 font-medium flex items-center justify-center gap-2 mt-4"
          >
            <Share2 size={16} /> Compartir
          </button>
        </div>
      </div>
      </div>
    );
  }

  return (
    <>
    <div className="-m-4 p-4" style={{ backgroundImage: `linear-gradient(rgba(245,245,244,0.55), rgba(245,245,244,0.65)), url(${FONDO_ESTADIO})`, backgroundSize: 'cover', backgroundPosition: 'center' }}>
    <div className="max-w-md mx-auto">
      <h1 className="text-lg font-medium text-stone-800 mb-3">Estadísticas</h1>
      <div className="flex gap-1 overflow-x-auto mb-4 pb-1">
        {[['ranking', 'Ranking'], ['estrellas', 'Estrellas de calidad'], ['duplas', 'Duplas y tríos'], ['h2h', 'Cabeza a cabeza'], ['rachas', 'Rachas'], ['grupo', 'Grupo']].map(([id, label]) => (
          <button
            key={id}
            onClick={() => setTab(id)}
            className={'px-3 py-1.5 rounded-full text-xs whitespace-nowrap ' + (tab === id ? 'bg-emerald-800 text-white' : 'bg-stone-100 text-stone-600')}
          >
            {label}
          </button>
        ))}
      </div>

      {tab === 'ranking' && (
        <div>
          <div className="flex items-center gap-2 mb-2">
            <h2 className="text-sm font-medium text-stone-600">Ranking</h2>
            <button onClick={() => setInfoAbierto('ranking')} className="w-5 h-5 rounded-full bg-red-600 text-white text-xs font-bold flex items-center justify-center flex-shrink-0">i</button>
          </div>
          <RankingTab stats={stats} onJugador={setJugadorId} />
          <BotonCompartirTab
            titulo="Ranking general"
            lineas={stats.ranking.slice().sort((a, b) => b.efectividad - a.efectividad).map((r) => ({ text: r.nombre + ' - ' + r.efectividad + '% (' + r.pj + ' PJ)' }))}
          />
        </div>
      )}
      {tab === 'estrellas' && (
        <div>
          <div className="flex items-center gap-2 mb-2">
            <h2 className="text-sm font-medium text-stone-600">Estrellas de calidad</h2>
            <button onClick={() => setInfoAbierto('estrellas')} className="w-5 h-5 rounded-full bg-red-600 text-white text-xs font-bold flex items-center justify-center flex-shrink-0">i</button>
          </div>
          <ListaCombinada
            items={(() => {
              const umbral = stats.UMBRAL_RESET_ESTRELLAS_DIAS;
              const esInactivo = (r) => r.diasSinJugar !== null && r.diasSinJugar > umbral;
              const activos = stats.estrellasRanking.filter((r) => !esInactivo(r));
              const inactivos = stats.estrellasRanking.filter((r) => esInactivo(r));
              return [...activos, ...inactivos];
            })()}
            vacio="Todavía no hay jugadores cargados."
            render={(p) => {
              const inactivo = p.diasSinJugar !== null && p.diasSinJugar > stats.UMBRAL_RESET_ESTRELLAS_DIAS;
              return (
                <div key={p.id} className={'border border-stone-200 rounded-xl p-3 mb-2 ' + (inactivo ? 'opacity-60' : '')} style={TARJETA_STATS}>
                  <div className="flex items-center justify-between mb-1.5">
                    <span className="text-sm text-stone-700">{p.nombre}</span>
                    <span className="text-sm font-medium text-emerald-700">{p.nivel ?? '-'}/10</span>
                  </div>
                  <UltimosCirculos resultados={p.resultados} />
                  <div className="mt-1.5">
                    <EstrellasRow nivel={p.nivel} />
                  </div>
                  {inactivo && <p className="text-xs text-stone-400 mt-1">Sin actividad reciente ({p.diasSinJugar} días) — nivel reseteado a 0</p>}
                  {!inactivo && p.nivel === null && <p className="text-xs text-stone-400 mt-1">Necesita 5 partidos jugados para calcular</p>}
                </div>
              );
            }}
          />
          <BotonCompartirTab
            titulo="Estrellas de calidad"
            lineas={stats.estrellasRanking.filter((p) => p.nivel !== null).map((p) => ({ text: p.nombre + ' - ' + p.nivel + '/10' }))}
          />
        </div>
      )}
      {tab === 'duplas' && (
        <div>
          <ListaCombinada
            items={stats.duplas}
            vacio="Todavía no hay duplas con 3 o más partidos jugados juntos."
            render={(d) => (
              <div key={d.a + d.b} className="flex items-center justify-between border border-stone-200 rounded-xl p-3 mb-2" style={TARJETA_STATS}>
                <span className="text-sm text-stone-700">{nombreDe(d.a)} + {nombreDe(d.b)}</span>
                <span className="text-sm font-medium text-emerald-700">{d.pct}% ({d.jugados} juntos)</span>
              </div>
            )}
          />
          <BotonCompartirTab
            titulo="Duplas y tríos"
            lineas={stats.duplas.map((d) => ({ text: nombreDe(d.a) + ' + ' + nombreDe(d.b) + ' - ' + d.pct + '%' }))}
          />
        </div>
      )}
      {tab === 'h2h' && (
        <div>
          <ListaCombinada
            items={stats.cabezaACabeza}
            vacio="Todavía no hay rivalidades con 3 o más enfrentamientos."
            render={(h) => (
              <div key={h.ganador + h.perdedor} className="flex items-center justify-between border border-stone-200 rounded-xl p-3 mb-2" style={TARJETA_STATS}>
                <span className="text-sm text-stone-700">{nombreDe(h.ganador)} le ganó a {nombreDe(h.perdedor)}</span>
                <span className="text-sm font-medium text-emerald-700">{h.n} veces</span>
              </div>
            )}
          />
          <BotonCompartirTab
            titulo="Cabeza a cabeza"
            lineas={stats.cabezaACabeza.map((h) => ({ text: nombreDe(h.ganador) + ' le ganó a ' + nombreDe(h.perdedor) + ' - ' + h.n + ' veces' }))}
          />
        </div>
      )}
      {tab === 'rachas' && (
        <div>
          <ListaCombinada
            items={stats.ranking.filter((r) => r.pj > 0).map((r) => ({ ...r, racha: stats.rachaDe(r.id) })).sort((a, b) => b.racha.mejorRachaGanadora - a.racha.mejorRachaGanadora)}
            vacio="Todavía no hay partidos jugados."
            render={(r) => (
              <div key={r.id} className="border border-stone-200 rounded-xl p-3 mb-2" style={TARJETA_STATS}>
                <p className="text-sm text-stone-700 mb-1.5">{r.nombre}</p>
                <div className="grid grid-cols-3 gap-2 text-center">
                  <div>
                    <p className="text-xs text-stone-400">Actual</p>
                    <p className="text-sm font-medium text-stone-800">
                      {r.racha.tipo ? r.racha.streak + ' ' + (r.racha.tipo === 'G' ? 'ganados' : r.racha.tipo === 'P' ? 'perdidos' : 'empatados') : '-'}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs text-stone-400">Mejor racha ganadora</p>
                    <p className="text-sm font-medium text-emerald-700">{r.racha.mejorRachaGanadora}</p>
                  </div>
                  <div>
                    <p className="text-xs text-stone-400">Peor racha perdedora</p>
                    <p className="text-sm font-medium text-red-600">{r.racha.mejorRachaPerdedora}</p>
                  </div>
                </div>
              </div>
            )}
          />
          <BotonCompartirTab
            titulo="Rachas"
            lineas={stats.ranking.filter((r) => r.pj > 0).map((r) => {
              const racha = stats.rachaDe(r.id);
              const actual = racha.tipo ? racha.streak + ' ' + (racha.tipo === 'G' ? 'ganados' : racha.tipo === 'P' ? 'perdidos' : 'empatados') : '-';
              return { text: r.nombre + ' - actual: ' + actual };
            })}
          />
        </div>
      )}
      {tab === 'grupo' && (
        <div>
          <div className="border border-stone-200 rounded-xl p-4 mb-3" style={TARJETA_STATS}>
            <p className="text-sm text-stone-500">Partidos que terminaron en empate</p>
            <p className="text-2xl font-medium text-stone-800">{stats.grupo.empates}%</p>
          </div>
          <p className="text-sm font-medium text-stone-500 mb-2">Ranking de asistencia</p>
          <div className="flex flex-col gap-2">
            {stats.grupo.asistencia.map((p) => (
              <div key={p.id} className="flex items-center justify-between border border-stone-200 rounded-xl p-3" style={TARJETA_STATS}>
                <span className="text-sm text-stone-700">{p.nombre}</span>
                <span className="text-sm font-medium text-emerald-700">{p.pct}%</span>
              </div>
            ))}
          </div>
          <BotonCompartirTab
            titulo="Estadísticas del grupo"
            subtitulo={'Empates: ' + stats.grupo.empates + '%'}
            lineas={stats.grupo.asistencia.map((p) => ({ text: p.nombre + ' - ' + p.pct + '% asistencia' }))}
          />
        </div>
      )}
    </div>
    </div>
    {infoAbierto && <InfoModal tipo={infoAbierto} onClose={() => setInfoAbierto(null)} />}
    </>
  );
}

function UltimosCirculos({ resultados }) {
  if (!resultados || resultados.length === 0) return <p className="text-xs text-stone-400">Sin partidos todavía</p>;
  const color = { V: 'bg-emerald-500', D: 'bg-red-500', E: 'bg-amber-400' };
  return (
    <div className="flex gap-1.5">
      {resultados.map((r, i) => (
        <div key={i} className={'w-3 h-3 rounded-full ' + color[r]} />
      ))}
    </div>
  );
}

function EstrellasRow({ nivel }) {
  if (nivel === null || nivel === undefined) {
    return <p className="text-xs text-stone-400">Necesita 5 partidos jugados</p>;
  }
  return (
    <div className="flex gap-0.5">
      {Array.from({ length: 10 }).map((_, i) => (
        <Star key={i} size={14} className={i < nivel ? 'text-amber-400 fill-amber-400' : 'text-stone-200'} />
      ))}
    </div>
  );
}

function BotonCompartirTab({ titulo, subtitulo, lineas }) {
  return (
    <button
      onClick={() => compartir({ titulo, subtitulo: subtitulo || 'Estadísticas', lineas })}
      className="w-full border border-stone-300 text-stone-700 rounded-lg py-3 font-medium flex items-center justify-center gap-2 mt-3 bg-white"
    >
      <Share2 size={16} /> Compartir esta solapa
    </button>
  );
}

const TABLA_CAMBIO_FILAS = [
  [5, 0, 0, 2], [4, 1, 0, 2], [4, 0, 1, 1], [3, 2, 0, 1], [3, 1, 1, 1], [3, 0, 2, 0],
  [2, 3, 0, 1], [2, 2, 1, 0], [2, 1, 2, 0], [2, 0, 3, -1], [1, 4, 0, 0], [1, 3, 1, 0],
  [1, 2, 2, 0], [1, 1, 3, -1], [1, 0, 4, -2], [0, 5, 0, 0], [0, 4, 1, -1], [0, 3, 2, -1],
  [0, 2, 3, -1], [0, 1, 4, -2], [0, 0, 5, -2],
];

function InfoModal({ tipo, onClose }) {
  return (
    <div className="fixed inset-0 bg-black bg-opacity-40 flex items-end justify-center z-10" style={{ position: 'absolute' }}>
      <div className="bg-white rounded-t-2xl p-5 w-full max-w-md max-h-[85vh] overflow-y-auto">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-medium text-stone-800">
            {tipo === 'ranking' ? 'Cómo funciona el Ranking' : 'Cómo funcionan las Estrellas de calidad'}
          </h2>
          <button onClick={onClose}><X size={20} className="text-stone-400" /></button>
        </div>

        {tipo === 'ranking' && (
          <div className="flex flex-col gap-3 text-sm text-stone-600">
            <p>Ordena a todos los jugadores por <strong>efectividad</strong>: el porcentaje de partidos ganados sobre el total jugado (victorias ÷ partidos jugados).</p>
            <p>Para entrar al orden numerado hace falta haber jugado al menos <strong>3 partidos</strong>. Con menos, el jugador igual aparece en la lista, pero abajo del todo y sin puesto, con la marca "falta para rankear".</p>
            <p>Si un jugador no jugó ningún partido en los últimos <strong>45 días</strong>, se lo considera inactivo: se corre al final de la lista para no ocupar los primeros puestos con datos viejos, pero <strong>no pierde nada</strong> — apenas vuelve a jugar, reingresa al grupo activo con toda su efectividad real.</p>
          </div>
        )}

        {tipo === 'estrellas' && (
          <div className="flex flex-col gap-3 text-sm text-stone-600">
            <p>Mide el <strong>nivel de forma reciente</strong> de cada jugador, del 0 al 10. No tiene relación con el nivel manual (1 a 5) que se usa para armar los equipos parejos.</p>
            <p>Se calcula mirando exclusivamente sus <strong>últimos 5 partidos jugados</strong> — hace falta llegar a 5 partidos en total para que empiece a calcularse.</p>
            <p>Arranca de una base de 5 estrellas, y sube o baja según la combinación exacta de victorias, empates y derrotas de esos 5 partidos:</p>
            <div className="border border-stone-200 rounded-xl overflow-hidden">
              <table className="w-full text-xs">
                <thead>
                  <tr className="bg-stone-50 text-stone-500">
                    <th className="text-center py-1.5 px-1">Victorias</th>
                    <th className="text-center py-1.5 px-1">Empates</th>
                    <th className="text-center py-1.5 px-1">Derrotas</th>
                    <th className="text-center py-1.5 px-1">Cambio</th>
                  </tr>
                </thead>
                <tbody>
                  {TABLA_CAMBIO_FILAS.map(([v, e, d, c], i) => (
                    <tr key={i} className="border-t border-stone-100">
                      <td className="text-center py-1 text-stone-700">{v}</td>
                      <td className="text-center py-1 text-stone-700">{e}</td>
                      <td className="text-center py-1 text-stone-700">{d}</td>
                      <td className={'text-center py-1 font-medium ' + (c > 0 ? 'text-emerald-600' : c < 0 ? 'text-red-600' : 'text-stone-400')}>
                        {c > 0 ? '+' + c : c}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <p>Si un jugador no jugó ningún partido en los últimos <strong>60 días</strong>, su nivel se resetea directamente a <strong>0</strong> — a diferencia del Ranking, acá sí se "borra" el valor, porque esta estadística busca reflejar el presente, no el historial.</p>
          </div>
        )}
      </div>
    </div>
  );
}

function StatCard({ label, value }) {
  return (
    <div className="rounded-lg p-3 text-center" style={{ backgroundColor: 'rgba(245,245,244,0.85)' }}>
      <p className="text-xs text-stone-400">{label}</p>
      <p className="text-lg font-medium text-stone-800">{value}</p>
    </div>
  );
}

function ListaCombinada({ items, vacio, render }) {
  if (items.length === 0) return <p className="text-stone-400 text-sm text-center py-10">{vacio}</p>;
  return <div className="flex flex-col gap-2">{items.map(render)}</div>;
}

function RankingTab({ stats, onJugador }) {
  const umbral = stats.UMBRAL_INACTIVIDAD_DIAS;
  const esInactivo = (r) => r.diasSinJugar !== null && r.diasSinJugar > umbral;
  const activos = stats.ranking.filter((r) => !esInactivo(r));
  const inactivos = stats.ranking.filter((r) => esInactivo(r));
  const conMinimo = activos.filter((r) => r.pj >= 3).sort((a, b) => b.efectividad - a.efectividad);
  const sinMinimo = activos.filter((r) => r.pj < 3);
  const inactivosOrdenados = inactivos.sort((a, b) => b.efectividad - a.efectividad);
  const todos = [...conMinimo, ...sinMinimo, ...inactivosOrdenados];
  if (stats.ranking.length === 0) return <p className="text-stone-400 text-sm text-center py-10">Todavía no hay jugadores cargados.</p>;
  return (
    <div className="flex flex-col gap-2">
      {todos.map((r, i) => (
        <button
          key={r.id}
          onClick={() => onJugador(r.id)}
          className={'flex items-center gap-3 border border-stone-200 rounded-xl p-3 text-left ' + (esInactivo(r) ? 'opacity-60' : '')}
          style={TARJETA_STATS}
        >
          <span className="text-xs text-stone-400 w-4">{r.pj >= 3 && !esInactivo(r) ? conMinimo.indexOf(r) + 1 : '-'}</span>
          <Avatar nombre={r.nombre} size={32} />
          <div className="flex-1 min-w-0">
            <p className="text-sm text-stone-800 truncate">{r.nombre}</p>
            <p className="text-xs text-stone-400">
              {esInactivo(r) ? 'Inactivo — ' + r.diasSinJugar + ' días sin jugar' : r.pj + ' PJ' + (r.pj < 3 ? ' · falta para rankear' : '')}
            </p>
          </div>
          <span className="text-sm font-medium text-emerald-700">{r.efectividad}%</span>
          <ChevronRight size={16} className="text-stone-300" />
        </button>
      ))}
    </div>
  );
}

// ---------- App ----------

function VistaPublica() {
  const [players, setPlayers] = useState([]);
  const [matches, setMatches] = useState([]);
  const [ready, setReady] = useState(false);
  const [seccion, setSeccion] = useState('stats');
  const [verId, setVerId] = useState(null);

  useEffect(() => {
    const ref = doc(db, 'users', PUBLIC_UID);
    const unsub = onSnapshot(
      ref,
      (snap) => {
        const data = snap.data() || {};
        setPlayers(data.players || []);
        setMatches(data.matches || []);
        setReady(true);
      },
      () => setReady(true)
    );
    return unsub;
  }, []);

  if (!ready) {
    return <div className="min-h-screen flex items-center justify-center text-stone-400 text-sm">Cargando...</div>;
  }

  const verPartido = verId ? matches.find((m) => m.id === verId) : null;
  const jugados = matches.filter((m) => m.estado === 'jugado');

  return (
    <div className="min-h-screen bg-stone-100">
      <div className="text-center text-xs text-stone-400 pt-3">Vista pública, solo lectura</div>
      <div className="flex justify-center gap-2 pt-3">
        <button
          onClick={() => { setSeccion('stats'); setVerId(null); }}
          className={'px-4 py-1.5 rounded-full text-sm ' + (seccion === 'stats' ? 'bg-emerald-800 text-white' : 'bg-stone-200 text-stone-600')}
        >
          Estadísticas
        </button>
        <button
          onClick={() => { setSeccion('historial'); setVerId(null); }}
          className={'px-4 py-1.5 rounded-full text-sm ' + (seccion === 'historial' ? 'bg-emerald-800 text-white' : 'bg-stone-200 text-stone-600')}
        >
          Historial de partidos
        </button>
      </div>
      <div className="p-4">
        {seccion === 'stats' && <StatsScreen players={players} matches={matches} />}
        {seccion === 'historial' && (
          <div className="max-w-md mx-auto">
            {verPartido ? (
              <>
                <button onClick={() => setVerId(null)} className="flex items-center gap-1 text-sm text-stone-500 mb-3">
                  <ChevronLeft size={16} /> Volver al historial
                </button>
                <ResumenPartido partido={verPartido} players={players} />
              </>
            ) : jugados.length === 0 ? (
              <p className="text-stone-400 text-sm text-center py-10">Todavía no hay partidos jugados.</p>
            ) : (
              <HistorialPartidos matches={matches} players={players} onSelect={setVerId} />
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default function App() {
  const modoPublico = typeof window !== 'undefined' && new URLSearchParams(window.location.search).get('stats') === '1';
  if (modoPublico) return <VistaPublica />;

  const [tab, setTab] = useState('jugadores');
  const [players, setPlayers] = useState([]);
  const [matches, setMatches] = useState([]);
  const [user, setUser] = useState(null);
  const [authReady, setAuthReady] = useState(false);
  const [ready, setReady] = useState(false);
  const [loginError, setLoginError] = useState('');

  useEffect(() => {
    const unsub = onAuthStateChanged(auth, (u) => {
      setUser(u);
      setAuthReady(true);
    });
    return unsub;
  }, []);

  useEffect(() => {
    if (!user) { setPlayers([]); setMatches([]); setReady(true); return; }
    setReady(false);
    const ref = doc(db, 'users', user.uid);
    const unsub = onSnapshot(
      ref,
      (snap) => {
        const data = snap.data() || {};
        setPlayers(data.players || []);
        setMatches(data.matches || []);
        setReady(true);
      },
      () => setReady(true)
    );
    return unsub;
  }, [user]);

  async function savePlayers(next) {
    setPlayers(next);
    if (!user) return;
    try { await setDoc(doc(db, 'users', user.uid), { players: next }, { merge: true }); } catch (e) {}
  }
  async function saveMatches(next) {
    setMatches(next);
    if (!user) return;
    try { await setDoc(doc(db, 'users', user.uid), { matches: next }, { merge: true }); } catch (e) {}
  }

  function iniciarSesion() {
    setLoginError('');
    signInWithPopup(auth, googleProvider).catch((e) => {
      setLoginError(e.code || e.message || 'Error desconocido al iniciar sesión');
    });
  }
  function cerrarSesion() {
    signOut(auth);
  }

  if (!authReady) {
    return <div className="min-h-screen flex items-center justify-center text-stone-400 text-sm">Cargando...</div>;
  }

  if (!user) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-stone-100 p-4">
        <div className="max-w-sm w-full">
          <div
            className="rounded-2xl px-6 text-center mb-4"
            style={{
              backgroundImage: `linear-gradient(rgba(15,110,86,0.55), rgba(15,110,86,0.85)), url(${FONDO_CANCHA})`,
              backgroundSize: 'cover',
              backgroundPosition: 'center',
              paddingTop: 56,
              paddingBottom: 56,
            }}
          >
            <p className="text-white text-2xl font-medium">FOBAL 5 APP</p>
            <p className="text-emerald-100 text-sm mt-1">Iniciá sesión para sincronizar tus datos en la nube</p>
          </div>
          <button onClick={iniciarSesion} className="w-full bg-white border border-stone-300 text-stone-800 rounded-lg py-3 font-medium">
            Iniciar sesión con Google
          </button>
          {loginError && <p className="text-xs text-red-600 mt-3 text-center">{loginError}</p>}
        </div>
      </div>
    );
  }

  if (!ready) {
    return <div className="min-h-screen flex items-center justify-center text-stone-400 text-sm">Cargando tus datos...</div>;
  }

  return (
    <div className="min-h-screen bg-stone-100 pb-20">
      <div className="flex items-center justify-between px-4 pt-3 text-xs text-stone-400">
        <span className="truncate">{user.displayName || user.email}</span>
        <button onClick={cerrarSesion} className="flex items-center gap-1 text-stone-500">
          <LogOut size={12} /> Cerrar sesión
        </button>
      </div>
      <div className="p-4">
        {tab === 'jugadores' && <JugadoresScreen players={players} savePlayers={savePlayers} />}
        {tab === 'partido' && <PartidoScreen players={players} matches={matches} saveMatches={saveMatches} />}
        {tab === 'stats' && <StatsScreen players={players} matches={matches} />}
      </div>
      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-stone-200 flex" style={{ position: 'sticky' }}>
        {TABS.map(({ id, label, icon: Icon }) => (
          <button
            key={id}
            onClick={() => setTab(id)}
            className={'flex-1 flex flex-col items-center gap-0.5 py-2.5 ' + (tab === id ? 'text-emerald-700' : 'text-stone-400')}
          >
            <Icon size={20} />
            <span className="text-[11px]">{label}</span>
          </button>
        ))}
      </div>
    </div>
  );
}
